EIA State Electricity Profiles


Here’s the code, if you’d like to read it
get_eia_sep &lt;- function(state, abbr){
  state_formatted &lt;- str_to_lower(state) |&gt; str_replace_all("\\s", "")

  dir_name &lt;- fs::path("data", "mp02")
  file_name &lt;- fs::path(dir_name, state_formatted)

  fs::dir_create(dir_name, recurse = TRUE)

  if(!fs::file_exists(file_name)){
    BASE_URL &lt;- "https://www.eia.gov"
    RESPONSE &lt;- request(BASE_URL) |&gt;
      req_url_path("electricity", "state", state_formatted) |&gt;
      req_headers(
        `User-Agent` = "Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:149.0) Gecko/20100101 Firefox/149.0"
      ) |&gt;
      req_retry(max_tries = 4) |&gt;
      req_perform(file_name)

    resp_check_status(RESPONSE)
  }

  TABLE &lt;- read_html(file_name) |&gt;
    html_element("table") |&gt;
    html_table() |&gt;
    mutate(Item = str_to_lower(Item))

  if("U.S. rank" %in% colnames(TABLE)){
    TABLE &lt;- TABLE |&gt; rename(Rank = `U.S. rank`)
  }

  CO2_MWh &lt;- TABLE |&gt;
    filter(Item == "carbon dioxide (lbs/mwh)") |&gt;
    pull(Value) |&gt;
    str_replace_all(",", "") |&gt;
    as.numeric()

  PRIMARY &lt;- TABLE |&gt;
    filter(Item == "primary energy source") |&gt;
    pull(Rank)

  RATE &lt;- TABLE |&gt;
    filter(Item == "average retail price (cents/kwh)") |&gt;
    pull(Value) |&gt;
    as.numeric()

  GENERATION_MWh &lt;- TABLE |&gt;
    filter(Item == "net generation (megawatthours)") |&gt;
    pull(Value) |&gt;
    str_replace_all(",", "") |&gt;
    as.numeric()

  data.frame(CO2_MWh               = CO2_MWh,
             primary_source        = PRIMARY,
             electricity_price_MWh = RATE * 10, # cents/kWh -&gt; $/MWh
             generation_MWh        = GENERATION_MWh,
             state                 = state,
             abbreviation          = abbr)
}

EIA_SEP_REPORT &lt;- map2(state.name, state.abb, get_eia_sep) |&gt; list_rbind()




NTD Energy Consumption


Here’s the code, if you’d like to read it
load_ntd_energy &lt;- function(){
  DATA_DIR &lt;- fs::path("data", "mp02")
  fs::dir_create(DATA_DIR, recurse = TRUE)

  NTD_ENERGY_FILE &lt;- fs::path(DATA_DIR, "2025_ntd_energy.xlsx")

  if(!fs::file_exists(NTD_ENERGY_FILE)){
    request("https://www.transit.dot.gov/") |&gt;
      req_url_path("sites", "fta.dot.gov", "files", "2026-09",
                   "2025 Energy Consumption_260806.xlsx") |&gt;
      req_headers(
        `User-Agent` = "Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:149.0) Gecko/20100101 Firefox/149.0") |&gt;
      req_perform(NTD_ENERGY_FILE)
  }

  if(file.info(NTD_ENERGY_FILE)$size &lt; 1e4){
    cat("I was unable to download the NTD Energy File. Please try again.\n")
    stop("Download failed. Please delete the corrupted file by running `unlink('data/mp02/2025_ntd_energy.xlsx')` and try again.")
  }

  to_numeric_fill_0 &lt;- function(x){
    x &lt;- if_else(x == "-", NA, x)
    replace_na(as.numeric(x), 0)
  }

  read_excel(NTD_ENERGY_FILE) |&gt;
    select(-c(`Reporter Type`, `Reporting Module`,
              `Gallons of Other Fuel`, `Other Fuel Description`)) |&gt;
    mutate(across(-c(`Agency Name`, `Mode`, `TOS`), to_numeric_fill_0)) |&gt;
    group_by(`NTD ID`, `Mode`, `Agency Name`) |&gt;
    summarize(across(where(is.numeric), sum), .groups = "keep") |&gt;
    mutate(ENERGY = sum(c_across(c(where(is.numeric))))) |&gt;
    filter(ENERGY &gt; 0) |&gt;
    select(-ENERGY) |&gt;
    ungroup()
}

NTD_ENERGY &lt;- load_ntd_energy()

# Convert NTD mode codes to readable names (used for both NTD tables)
recode_mode &lt;- function(x){
  recode_values(x,
    "AR" ~ "Alaska Railroad",
    "CB" ~ "Commuter Bus",
    "CC" ~ "Cable Car",
    "CR" ~ "Commuter Rail",
    "DR" ~ "Demand Response",
    "DT" ~ "Demand Response - Taxi",
    "FB" ~ "Ferryboat",
    "HR" ~ "Heavy Rail",
    "IP" ~ "Inclined Plane",
    "LR" ~ "Light Rail",
    "MB" ~ "Bus",
    "MG" ~ "Monorail / Automated Guideway",
    "OR" ~ "Other Rail",
    "PB" ~ "Publico",
    "RB" ~ "Bus Rapid Transit",
    "SR" ~ "Streetcar Rail",
    "TB" ~ "Trolleybus",
    "TR" ~ "Aerial Tramway",
    "VP" ~ "Vanpool",
    "YR" ~ "Hybrid Rail",
    default = "Unknown")
}

NTD_ENERGY &lt;- NTD_ENERGY |&gt; mutate(Mode = recode_mode(Mode))


During data preparation, a small number of non-numeric and suppressed entries within the NTD energy consumption records were coerced to zero to ensure consistent aggregation across fuel categories without dropping valid service agencies.


NTD Service Data
To address a critical data loss issue where SQL NULL values propagated across rows, causing total ridership to drop out for nearly 90% of services (including all MTA New York City Transit lines), we revised the ridership compilation logic. Because ADA paratransit and sponsored trip fields are naturally blank for standard fixed-route transit, we imported the unlinked passenger trip categories independently and used coalesce(..., 0) to treat blank values as zero before summing.


Here’s the code, if you’d like to read it
load_ntd_service &lt;- function(){
  DATA_DIR &lt;- fs::path("data", "mp02")
  fs::dir_create(DATA_DIR, recurse = TRUE)

  NTD_SERVICE_FILE &lt;- fs::path(DATA_DIR, "2025_ntd_service.csv")

  if(!fs::file_exists(NTD_SERVICE_FILE)){
    request("https://data.transportation.gov/resource/4fir-qbim.csv") |&gt;
      req_url_query(`$query` = paste(
        "SELECT  `_5_digit_ntd_id` AS `NTD_ID`",
        "`max_agency` AS `AGENCY`",
        "`max_reporter_type` AS `reporter_type`",
        "`max_organization_type` AS `organization_type`",
        "`max_city` AS `city`",
        "`max_state` AS `state`",
        "`mode`",
        "`type_of_service`",
        "`max_primary_uza_code` as `uza_code`",
        "`max_primary_uza_name` as `uza_name`",
        "`max_primary_uza_area_sq_miles` as `uza_sq_miles`",
        "`max_primary_uza_population` as `uza_population`",
        "`max_service_area_sq_miles` as `service_area_sq_miles`",
        "`max_service_area_population` as `service_area_population`",
        "`questionable_record` as `flagged_likely_inaccurate`",
        # Pull the three trip counts separately: adding them in SQL turns the
        # total into NA whenever ADA or sponsored trips are blank
        "`sum_unlinked_passenger_trips_upt` as `upt`",
        "`sum_ada_upt` as `ada_upt`",
        "`sum_sponsored_service_upt` as `sponsored_upt`",
        "`sum_passenger_miles` WHERE caseless_one_of(`report_year`, '2025') limit 50000",
        sep = ",")) |&gt;
      req_headers(
        `User-Agent` = "Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:149.0) Gecko/20100101 Firefox/149.0") |&gt;
      req_perform(NTD_SERVICE_FILE)
  }

  if(file.info(NTD_SERVICE_FILE)$size &lt; 1e4){
    cat("I was unable to download the NTD Service File. Please try again.\n")
    stop("Download failed. Please delete the corrupted file by running `unlink('data/mp02/2025_ntd_service.csv')` and try again.")
  }

  read_csv(NTD_SERVICE_FILE, show_col_types = FALSE) |&gt;
    mutate(flagged_likely_inaccurate = !is.na(flagged_likely_inaccurate),
           # Treat missing trip counts as zero so one blank column
           # doesn't wipe out an agency's total ridership
           total_upt = coalesce(upt, 0) + coalesce(ada_upt, 0) + coalesce(sponsored_upt, 0))
}

NTD_SERVICE &lt;- load_ntd_service()
